def evaluate(board: SimpleBoard) -> float:
    """Simple evaluation: material + basic positional factors"""
    score = 0

    # Material
    for piece in board.pieces.values():
        value = PIECE_VALUES.get(piece[1], 0)
        if piece[0] == 'w':
            score += value
        else:
            score -= value

    # King safety (penalize central king in early game)
    # Find kings
    wk = board.find_king('w')
    bk = board.find_king('b')

    if wk:
        file = ord(wk[0]) - ord('a')
        rank = int(wk[1]) - 1
        if 2 <= file <= 5 and 2 <= rank <= 5:
            score -= 0.3

    if bk:
        file = ord(bk[0]) - ord('a')
        rank = int(bk[1]) - 1
        if 2 <= file <= 5 and 2 <= rank <= 5:
            score += 0.3

    # Central control bonus
    center = ['d4', 'e4', 'd5', 'e5']
    for sq in center:
        piece = board.pieces.get(sq)
        if piece:
            if piece[0] == 'w':
                score += 0.15
            else:
                score -= 0.15

    return score

def minimax_search(board: SimpleBoard, depth: int, maximizing: bool) -> Tuple[float, Optional[str]]:
    """Minimax with alpha-beta pruning"""
    if depth == 0:
        return evaluate(board), None

    legal_moves = get_legal_moves(board)
    if not legal_moves:
        if board.is_check(board.to_play[0]):
            return -10000 if maximizing else 10000, None
        return 0, None

    # Move ordering: captures first
    scored_moves = []
    for move in legal_moves:
        to_sq = move[2:4]
        captured = board.pieces.get(to_sq)
        if captured:
            # MVV-LVA: Most Valuable Victim - Least Valuable Aggressor
            # Simple: prioritize captures of high-value pieces
            score = 10 + PIECE_VALUES.get(captured[1], 0)
            scored_moves.append((-score, move))
        else:
            scored_moves.append((0, move))

    scored_moves.sort()

    best_move = None

    if maximizing:
        max_eval = -math.inf
        for _, move in scored_moves:
            new_board = board.make_move(move)
            eval, _ = minimax_search(new_board, depth - 1, False)
            if eval > max_eval:
                max_eval = eval
                best_move = move
        return max_eval, best_move
    else:
        min_eval = math.inf
        for _, move in scored_moves:
            new_board = board.make_move(move)
            eval, _ = minimax_search(new_board, depth - 1, True)
            if eval < min_eval:
                min_eval = eval
                best_move = move
        return min_eval, best_move

def policy(pieces: dict[str, str], to_play: str) -> str:
    """Main policy function"""
    board = SimpleBoard(pieces, to_play)
    legal_moves = get_legal_moves(board)

    if not legal_moves:
        return ""

    # 1. Check for immediate checkmate
    for move in legal_moves:
        new_board = board.make_move(move)
        opp_legal_moves = get_legal_moves(new_board)
        if not opp_legal_moves and new_board.is_check(new_board.to_play[0]):
            return move

    # 2. Look for good captures (queen or rook)
    best_capture = None
    best_value = 0
    for move in legal_moves:
        to_sq = move[2:4]
        captured = board.pieces.get(to_sq)
        if captured:
            value = PIECE_VALUES.get(captured[1], 0)
            if value >= 5 and value > best_value:  # Rook or better
                best_value = value
                best_capture = move

    if best_capture:
        return best_capture

    # 3. Search with minimax (depth 2 or 3 depending on move count)
    try:
        # If few pieces, search deeper
        piece_count = len(board.pieces)
        depth = 3 if piece_count <= 10 else 2

        _, best_move = minimax_search(board, depth, True)
        if best_move:
            return best_move
    except:
        # If search fails, fallback
        pass

    # 4. Fallback: random legal move
    return random.choice(legal_moves)
