            if to_sq[0] == 'g':  # Kingside
                rook_from = f'h{rank}'
                rook_to = f'f{rank}'
            else:  # Queenside
                rook_from = f'a{rank}'
                rook_to = f'd{rank}'

            if rook_from in new_board.pieces:
