                del new_board.pieces[rook_from]

        # En passant capture
        if piece[1] == 'P' and to_sq == self.en_passant:
            dir_ = 1 if piece[0] == 'w' else -1
            captured_sq = f"{to_sq[0]}{int(to_sq[1]) - dir_}"
            if captured_sq in new_board.pieces:
                del new_board.pieces[captured_sq]

        # Update en passant target
        if piece[1] == 'P' and abs(int(from_sq[1]) - int(to_sq[1])) == 2:
            dir_ = 1 if piece[0] == 'w' else -1
            new_board.en_passant = f"{from_sq[0]}{int(from_sq[1]) + dir_}"
        else:
            new_board.en_passant = None

        # Move piece
        new_piece = piece
        if promo:
            new_piece = piece[0] + promo.upper()

        new_board.pieces[to_sq] = new_piece
        del new_board.pieces[from_sq]

        # Update castling rights
        if piece[1] == 'K':
            new_board.castle_rights = {'K': False, 'Q': False}
        elif piece[1] == 'R':
            if from_sq == 'a1':
                new_board.castle_rights['Q'] = False
            elif from_sq == 'h1':
                new_board.castle_rights['K'] = False
            elif from_sq == 'a8':
                new_board.castle_rights['Q'] = False
            elif from_sq == 'h8':
                new_board.castle_rights['K'] = False

        # Switch turn
        new_board.to_play = 'black' if self.to_play == 'white' else 'white'

        return new_board

def get_legal_moves(board: ChessBoard) -> List[str]:
    """Get all legal moves by filtering pseudo-legal moves"""
    pseudo_moves = board.generate_pseudo_legal_moves()
    legal_moves = []

    for move in pseudo_moves:
        new_board = board.make_move(move)
        # Move is legal if our king is not in check after making it
        if not new_board.is_king_in_check(board.to_play[0]):
            legal_moves.append(move)

    return legal_moves

