                piece = self.get_piece(self.coords_to_sq(nf, nr))
                if piece:
                    if piece[0] == by_color:
                        pt = piece[1]
                        if (df, dr) in [(1, 0), (-1, 0), (0, 1), (0, -1)] and pt in ['R', 'Q']:
