                rook_to = f'd{rank}'
            if rook_from in new_board.pieces:
                new_board.pieces[rook_to] = new_board.pieces[rook_from]
                del new_board.pieces[rook_from]

        # En passant
        if piece[1] == 'P' and to_sq == self.en_passant:
