    """Return all legal moves"""
    moves = board.generate_moves()
    legal = []
    for move in moves:
        new_board = board.make_move(move)
        if not new_board.in_check(board.to_play[0]):
            legal.append(move)
    return legal

def evaluate(board: Board) -> float:
    """Evaluate position from to_play perspective"""
    score = 0
    for piece in board.pieces.values():
        value = PIECE_VALUES[piece[1]]
        if piece[0] == 'w':
            score += value
        else:
            score -= value

    # King safety
    wk = board.find_king('w')
    bk = board.find_king('b')
    if wk:
        wf, wr = board.sq_to_coords(wk)
        if 2 <= wf <= 5 and 2 <= wr <= 5:
            score -= 0.5
    if bk:
        bf, br = board.sq_to_coords(bk)
        if 2 <= bf <= 5 and 2 <= br <= 5:
            score += 0.5

    if board.to_play == 'black':
        score = -score

    return score

def minimax(board: Board, depth: int, alpha: float, beta: float, maximizing: bool) -> Tuple[float, Optional[str]]:
    """Alpha-beta search"""
    if depth == 0:
        return evaluate(board), None

    moves = get_legal_moves(board)
    if not moves:
        if board.in_check(board.to_play[0]):
            return -10000 if maximizing else 10000, None
        return 0, None

    # Move ordering: captures first
    moves.sort(key=lambda m: (0 if not board.get_piece(m[2:4]) else -PIECE_VALUES.get(board.get_piece(m[2:4])[1], 0)))

    best_move = None

    if maximizing:
        max_eval = -math.inf
        for move in moves:
            eval, _ = minimax(board.make_move(move), depth - 1, alpha, beta, False)
            if eval > max_eval:
                max_eval = eval
                best_move = move
            alpha = max(alpha, eval)
            if beta <= alpha:
                break
        return max_eval, best_move
    else:
        min_eval = math.inf
        for move in moves:
            eval, _ = minimax(board.make_move(move), depth - 1, alpha, beta, True)
            if eval < min_eval:
                min_eval = eval
                best_move = move
            beta = min(beta, eval)
            if beta <= alpha:
                break
        return min_eval, best_move

def policy(pieces: dict[str, str], to_play: str) -> str:
    """Select best move"""
    board = Board(pieces, to_play)
    moves = get_legal_moves(board)

    if not moves:
        return ""

    # Checkmate?
    for move in moves:
        b = board.make_move(move)
        if not get_legal_moves(b) and b.in_check(b.to_play[0]):
            return move

    # Big capture?
    best_capture = None
    best_val = -1
    for move in moves:
        cap = board.get_piece(move[2:4])
        if cap:
            val = PIECE_VALUES[cap[1]]
            if val >= 5 and val > best_val:
                best_val = val
                best_capture = move

    if best_capture:
        return best_capture

    # Search
    depth = 3 if len(board.pieces) <= 10 else 2
    try:
        _, best = minimax(board, depth, -math.inf, math.inf, True)
        if best:
            return best
    except:
        pass

    return best_capture or random.choice(moves)
